import{_ as o,l as s,o as e,c,v as r,p as i,x as t,d as l,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"页缓存","description":"","frontmatter":{"title":"页缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-cache.md","filePath":"cs/page-cache.md","lastUpdated":1789023840000}'),p={name:"cs/page-cache.md"};function m(_,a,f,u,E,C){const d=s("Mermaid");return e(),c("div",null,[a[1]||(a[1]=r('<h1 id="页缓存" tabindex="-1">页缓存 <a class="header-anchor" href="#页缓存" aria-label="Permalink to &quot;页缓存&quot;">​</a></h1><div class="epigraph"><p>每个文件的数据页按文件偏移索引放在统一的页 Cache 里；read、write 与 mmap 看见同一帧。</p><footer>—— 据 McKusick 对缓冲缓存的演进；Bovet and Cesati 对 address_space 的整理</footer></div><p><a href="/cs/buffer-dirty">上一课</a>已经承认脏页与「同一物理块不应有两份副本」。缺口是把缓存收成<strong>按 inode 索引的页集合</strong>：不是块设备上的 512 字节缓冲槽那么老的主线，而是与 <a href="/cs/demand-paging">按需调页</a> 同一粒度的页。mmap 缺页填的就是这里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旧 Unix 缓冲缓存按设备+块号。文件空洞、大文件、mmap 需要按「文件偏移」找页，并允许稀疏。缺口：<code>address_space</code>（或等价物）用基数树/xarray 把索引 → 页框。<code>read</code> 拷到用户前先找页；未命中则 <code>readpage</code> 经 <a href="/cs/vfs">VFS</a> 让 FS 填。同一页可被多进程 mmap 共享。shrinker 从这里丢干净页。</p><p>本课不把 xarray 的内部节点写成算法课。</p><p><span class="marginnote">缓冲头（buffer_head）仍可把一页拆成多个盘块，对接非页对齐的块大小。教学上页是主对象，块是填充单位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查 inode 的页 Cache，miss 则向 <a href="/cs/buddy-allocator">buddy</a> 要页、发起读、插入树、拷贝或映射给用户。写：找或建页，改内容，标脏。匿名页不进这份按文件的树（它们走匿名 LRU）。与 dcache 分工不变：dentry 是名，页 Cache 是字节。</p>',9)),(e(),i(h,null,{default:t(()=>[n(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E6%96%87%E4%BB%B6%E5%81%8F%E7%A7%BB%22%5D%20--%3E%20TREE%5B%22inode%20%E9%A1%B5%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20HIT%5B%22%E5%90%8C%E4%B8%80%E5%B8%A7%E4%BE%9B%20read%2Fmmap%22%5D%0A%20%20TREE%20--%3E%20MISS%5B%22readpage%20%E5%A1%AB%E9%A1%B5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>页 Cache 让「磁盘是内存的下一层」可实现：热点文件留在 RAM，工作集可以主要是文件页。回收时丢掉它们等于缩小 Cache，不是杀进程。不要把页 Cache 当成 CPU 数据 Cache 的同构数字；缺失代价是毫秒级 I/O。数据库栏的缓冲池是用户态另一套，可以 <code>O_DIRECT</code> 绕过本课对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>fadvise</code> 的全部提示。不保证页 Cache 与块设备硬件 Cache 的一致性协议。下一课：脏页何时由谁写成队列，而不是等置换偶然碰到。</p><p>后课默认：文件字节在按偏移索引的页里。后台把脏页推向设备，下一课 writeback。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>页 Cache 按文件偏移索引帧；读写映射共用。</li><li>miss 走 VFS 的 readpage；shrinker 可丢干净页。</li><li>脏页的主动回写是 writeback 的缺口。</li><li>出处：McKusick et al., <em>4.4BSD</em>；Bovet and Cesati, <em>ULK</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',7))])}const T=o(p,[["render",m]]);export{b as __pageData,T as default};
